const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-Q",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        publish_request: null,
        platform_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const payload = source.payload || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-Q will not prepare publishing handoff when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "prepare_publish") {
  return fail({
    code: "PUBLISHING_NOT_REQUESTED",
    message: "source.next_action is not prepare_publish.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.platform) {
  return fail({
    code: "MISSING_PLATFORM",
    message: "config.platform is required."
  });
}

if (!config.mode) {
  return fail({
    code: "MISSING_MODE",
    message: "config.mode is required."
  });
}

if (!config.publish_type) {
  return fail({
    code: "MISSING_PUBLISH_TYPE",
    message: "config.publish_type is required."
  });
}

const platform = normalizeString(config.platform).toLowerCase();
const mode = normalizeString(config.mode).toLowerCase();
const publishType = normalizeString(config.publish_type).toLowerCase();

const supportedPlatforms = ["linkedin", "wordpress", "webflow", "x_twitter", "manual"];
const supportedModes = ["platform_handoff", "manual_publish_handoff"];
const supportedPublishTypes = ["social_post", "blog_post", "cms_page", "short_post", "manual_publish"];

if (!supportedPlatforms.includes(platform)) {
  return fail({
    code: "UNSUPPORTED_PLATFORM",
    message: "config.platform is not supported in C2-Q v1.",
    details: [{ platform, supported_platforms: supportedPlatforms }]
  });
}

if (!supportedModes.includes(mode)) {
  return fail({
    code: "UNSUPPORTED_MODE",
    message: "config.mode is not supported in C2-Q v1.",
    details: [{ mode, supported_modes: supportedModes }]
  });
}

if (!supportedPublishTypes.includes(publishType)) {
  return fail({
    code: "UNSUPPORTED_PUBLISH_TYPE",
    message: "config.publish_type is not supported in C2-Q v1.",
    details: [{ publish_type: publishType, supported_publish_types: supportedPublishTypes }]
  });
}

if (Array.isArray(config.allowed_platforms) && config.allowed_platforms.length > 0) {
  if (!config.allowed_platforms.includes(platform)) {
    return fail({
      code: "PLATFORM_NOT_ALLOWED",
      message: "config.platform is not allowed by config.allowed_platforms.",
      details: [
        {
          platform,
          allowed_platforms: config.allowed_platforms
        }
      ]
    });
  }
}

if (Array.isArray(config.allowed_publish_types) && config.allowed_publish_types.length > 0) {
  if (!config.allowed_publish_types.includes(publishType)) {
    return fail({
      code: "PUBLISH_TYPE_NOT_ALLOWED",
      message: "config.publish_type is not allowed by config.allowed_publish_types.",
      details: [
        {
          publish_type: publishType,
          allowed_publish_types: config.allowed_publish_types
        }
      ]
    });
  }
}

if (config.approval_status_required === true) {
  const approved = source.approved_action?.approved === true;
  if (!approved) {
    return fail({
      code: "PUBLISH_NOT_APPROVED",
      message: "Approved action is required before preparing publishing handoff.",
      details: [{ approved_action: source.approved_action || null }]
    });
  }
}

const title = normalizeString(payload.title);
const body = normalizeString(payload.body);
const contentType = normalizeString(payload.content_type || publishType);
const originalPlatform = normalizeString(payload.platform || platform);

if (!body) {
  return fail({
    code: "MISSING_BODY",
    message: "input.payload.body is required."
  });
}

if (platform === "manual" && mode !== "manual_publish_handoff") {
  return fail({
    code: "INVALID_PLATFORM_MODE",
    message: "Manual platform supports manual_publish_handoff mode only.",
    details: [{ platform, mode }]
  });
}

if (platform !== "manual" && mode !== "platform_handoff") {
  return fail({
    code: "INVALID_PLATFORM_MODE",
    message: "Publishing platforms support platform_handoff mode only.",
    details: [{ platform, mode }]
  });
}

const publishingRules = config.publishing_rules || {};
const allowDirectPublish = publishingRules.allow_direct_publish === true;
const defaultStatus = publishingRules.default_status || "draft_ready";
const requireHumanPublishReview = publishingRules.require_human_publish_review !== false;

if (allowDirectPublish === true) {
  return fail({
    code: "DIRECT_PUBLISH_NOT_ALLOWED_IN_V1",
    message: "C2-Q v1 does not directly publish. Set allow_direct_publish to false and use platform handoff."
  });
}

if (platform === "x_twitter") {
  const maxCharacterCount = Number(publishingRules.max_character_count || 280);
  if (body.length > maxCharacterCount) {
    return fail({
      code: "BODY_EXCEEDS_CHARACTER_LIMIT",
      message: "Body exceeds configured max_character_count.",
      details: [
        {
          body_length: body.length,
          max_character_count: maxCharacterCount
        }
      ]
    });
  }
}

const publishRequest = {
  platform,
  mode,
  status: defaultStatus,
  publish_type: publishType,
  content_type: contentType,
  title: title || null,
  body,
  slug: payload.slug || null,
  excerpt: payload.excerpt || payload.summary || null,
  tags: Array.isArray(payload.tags) ? payload.tags : [],
  cta: payload.cta || null,
  source_platform: originalPlatform || null,
  requires_approval: config.requires_approval === true,
  approval_status_required: config.approval_status_required === true,
  human_publish_review_required: requireHumanPublishReview,
  prepared_at: nowIso()
};

let platformPayload = {};
let platformHandoff = null;
let manualReviewHandoff = null;
let nextAction = config.default_next_action || "publish_handoff_ready";

if (mode === "platform_handoff") {
  if (platform === "linkedin") {
    platformPayload = {
      platform,
      action: "prepare_linkedin_post",
      text: body,
      title: title || null,
      visibility: config.linkedin?.visibility || "PUBLIC",
      publish_status: defaultStatus
    };
  }

  if (platform === "wordpress") {
    platformPayload = {
      platform,
      action: "create_or_update_post",
      site_id: config.wordpress?.site_id || null,
      post_status: config.wordpress?.post_status || defaultStatus || "draft",
      title,
      content: body,
      slug: payload.slug || null,
      excerpt: payload.excerpt || null,
      category: config.wordpress?.category || null,
      tags: Array.isArray(payload.tags) ? payload.tags : []
    };
  }

  if (platform === "webflow") {
    platformPayload = {
      platform,
      action: "create_or_update_cms_item",
      site_id: config.webflow?.site_id || null,
      collection_id: config.webflow?.collection_id || null,
      publish_to_live: config.webflow?.publish_to_live === true,
      fields: {
        name: title || payload.slug || "Untitled",
        slug: payload.slug || null,
        body,
        summary: payload.summary || payload.excerpt || null
      }
    };
  }

  if (platform === "x_twitter") {
    platformPayload = {
      platform,
      action: "prepare_tweet",
      text: body,
      character_count: body.length,
      max_character_count: Number(publishingRules.max_character_count || 280),
      publish_status: defaultStatus
    };
  }

  platformHandoff = {
    next_component: `${platform}_publishing_adapter`,
    input: {
      success: true,
      component_id: "C2-Q",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "publishing_provider_request",
      publish_request: publishRequest,
      platform_payload: platformPayload,
      source_result: source,
      error: null,
      next_action: "publish_or_save_draft"
    },
    config: {
      platform,
      adapter_required: true,
      direct_publish_allowed: false,
      default_next_action: "track_publish_status"
    }
  };

  nextAction = config.default_next_action || "create_publish_handoff";
}

if (mode === "manual_publish_handoff") {
  manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C2-Q",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "manual_publish_review",
      publish_request: publishRequest,
      source_result: source,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "manual_publish",
      review_reason: "Manual publishing required.",
      reviewer_email: config.reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "marketing",
      priority: config.priority || "normal",
      allowed_actions: ["publish_manually", "edit_content", "reject_publish", "request_revision"],
      default_next_action: "notify_reviewer"
    }
  };

  nextAction = "manual_review";
}

return [
  {
    json: {
      success: true,
      component_id: "C2-Q",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      publish_request: publishRequest,
      platform_handoff: platformHandoff,
      manual_review_handoff: manualReviewHandoff,
      source_result: source,
      error: null,
      next_action: nextAction
    }
  }
];
